(606,431,$mw$0B39D90E0ECF30507E26E2B4EEA7103D39FEC4A506260B40120CC6075BA7CB56$mw$,$mw$5286ba1fe5d3ae2aa5b9360e7ace407f$mw$,$mw$$mw$,$mw${"Id":431,"StageId":2,"CategoryId":22,"Points":10,"TitleAr":"تفسير تأثير إضافة ثابت على المتوسط","TitleEn":"Explain the effect of shifting all observations on the mean","QuestionTextAr":"إذا أضفنا 3 إلى كل مشاهدة في مجموعة بيانات، كيف يتغير المتوسط الحسابي؟","QuestionTextEn":"If 3 is added to every observation in a data set, how does its mean change?","DetailedSolutionAr":"المبدأ المستخدم: المتوسط الحسابي = مجموع القيم ÷ عددها. إذا أضفنا 3 إلى كل قيمة من ن قيم، يزداد المجموع بمقدار 3ن؛ بالتالي المتوسط الجديد = (المجموع + 3ن) ÷ ن = المتوسط القديم + 3. إذن يزداد المتوسط بمقدار 3.","DetailedSolutionEn":"Rule used: Mean = sum ÷ count. Adding 3 to each of n observations adds 3n to the sum. New mean = (sum + 3n)/n = old mean + 3. Therefore the mean increases by exactly 3.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":1713,"Order":1,"LatexCode":"+3","IsCorrect":true},{"Id":1714,"Order":2,"LatexCode":"+1","IsCorrect":false},{"Id":1715,"Order":3,"LatexCode":"\\times3","IsCorrect":false},{"Id":1716,"Order":4,"LatexCode":"0","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"فكّر في أثر التغيير على مجموع البيانات وعددها.","En":"Consider how the total and count change."},{"Ar":"اكتب المتوسط الجديد باستعمال مجموع القيم بعد الإضافة.","En":"Express the new mean using the shifted sum."}],"Title":{"Ar":"تفسير تأثير إضافة ثابت على المتوسط","En":"Explain the effect of shifting all observations on the mean"},"Points":10,"Options":[{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"+3"},{"Reason":{"Ar":"الزيادة لكل مشاهدة هي 3؛ بعد القسمة على عدد المشاهدات تظل 3 لا 1.","En":"The shift is 3 per observation; averaging gives a shift of 3, not 1."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"+1"},{"Reason":{"Ar":"هذا أثر ضرب القيم في 3، لا إضافة 3 إليها.","En":"This would describe multiplying every observation by 3, not adding 3."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"\\times3"},{"Reason":{"Ar":"المتوسط يتغير لأن المجموع يزداد بمقدار موجب وعدد القيم ثابت.","En":"The mean changes because the sum increases while the count stays fixed."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"0"}],"StageId":2,"Question":{"Ar":"إذا أضفنا 3 إلى كل مشاهدة في مجموعة بيانات، كيف يتغير المتوسط الحسابي؟","En":"If 3 is added to every observation in a data set, how does its mean change?"},"Solution":{"Idea":{"Ar":"إضافة ثابت لكل قيمة تنقل المتوسط بالمقدار نفسه.","En":"Adding a constant to every value shifts the mean by that constant."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"لتكن المشاهدات $x_1,\\ldots,x_n$ وعددها $n>0$. المتوسط الأصلي هو مجموعها مقسوماً على $n$.","En":"Let the observations be $x_1,\\ldots,x_n$ with $n>0$. The original mean is their sum divided by $n$."},{"Ar":"تضيف الزيادة 3 إلى كل مشاهدة مقداراً كلياً قدره $3n$ إلى المجموع.","En":"Adding 3 to every observation adds a total of $3n$ to the sum."},{"Ar":"عند القسمة على $n$ تساوي زيادة المتوسط $3n/n=3$.","En":"Dividing by $n$ gives a mean increase of $3n/n=3$."}],"Result":{"Ar":"$+3$","En":"$+3$"},"CommonError":{"Ar":"لا تضرب المتوسط في الثابت عند إضافته.","En":"Do not multiply the mean when a constant is added."},"FormulaLatex":"\\overline{x+c}=\\bar{x}+c","Substitution":{"Ar":"$\\frac{\\sum x_i+3n}{n}=\\bar{x}+3$","En":"$\\frac{\\sum x_i+3n}{n}=\\bar{x}+3$"},"Verification":{"Ar":"مثلاً متوسط $(2,4)$ هو 3، ومتوسط $(5,7)$ هو 6؛ الفرق 3.","En":"For example, $(2,4)$ has mean 3 and $(5,7)$ has mean 6; the difference is 3."}},"TrackIds":[7],"CategoryId":22,"PrimarySkillId":99,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"فكّر في أثر التغيير على مجموع البيانات وعددها.","En":"Consider how the total and count change."},{"Ar":"اكتب المتوسط الجديد باستعمال مجموع القيم بعد الإضافة.","En":"Express the new mean using the shifted sum."}],"Solution":{"Idea":{"Ar":"إضافة ثابت لكل قيمة تنقل المتوسط بالمقدار نفسه.","En":"Adding a constant to every value shifts the mean by that constant."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"لتكن المشاهدات $x_1,\\ldots,x_n$ وعددها $n>0$. المتوسط الأصلي هو مجموعها مقسوماً على $n$.","En":"Let the observations be $x_1,\\ldots,x_n$ with $n>0$. The original mean is their sum divided by $n$."},{"Ar":"تضيف الزيادة 3 إلى كل مشاهدة مقداراً كلياً قدره $3n$ إلى المجموع.","En":"Adding 3 to every observation adds a total of $3n$ to the sum."},{"Ar":"عند القسمة على $n$ تساوي زيادة المتوسط $3n/n=3$.","En":"Dividing by $n$ gives a mean increase of $3n/n=3$."}],"Result":{"Ar":"$+3$","En":"$+3$"},"CommonError":{"Ar":"لا تضرب المتوسط في الثابت عند إضافته.","En":"Do not multiply the mean when a constant is added."},"FormulaLatex":"\\overline{x+c}=\\bar{x}+c","Substitution":{"Ar":"$\\frac{\\sum x_i+3n}{n}=\\bar{x}+3$","En":"$\\frac{\\sum x_i+3n}{n}=\\bar{x}+3$"},"Verification":{"Ar":"مثلاً متوسط $(2,4)$ هو 3، ومتوسط $(5,7)$ هو 6؛ الفرق 3.","En":"For example, $(2,4)$ has mean 3 and $(5,7)$ has mean 6; the difference is 3."}},"Distractors":[{"ErrorType":"","Reason":null,"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"الزيادة لكل مشاهدة هي 3؛ بعد القسمة على عدد المشاهدات تظل 3 لا 1.","En":"The shift is 3 per observation; averaging gives a shift of 3, not 1."},"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"هذا أثر ضرب القيم في 3، لا إضافة 3 إليها.","En":"This would describe multiplying every observation by 3, not adding 3."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"المتوسط يتغير لأن المجموع يزداد بمقدار موجب وعدد القيم ثابت.","En":"The mean changes because the sum increases while the count stays fixed."},"Order":4}]}$mw$,$mw$إضافة ثابت لكل قيمة تنقل المتوسط بالمقدار نفسه.

$\overline{x+c}=\bar{x}+c$

1. لتكن المشاهدات $x_1,\ldots,x_n$ وعددها $n>0$. المتوسط الأصلي هو مجموعها مقسوماً على $n$.

2. تضيف الزيادة 3 إلى كل مشاهدة مقداراً كلياً قدره $3n$ إلى المجموع.

3. عند القسمة على $n$ تساوي زيادة المتوسط $3n/n=3$.

$\frac{\sum x_i+3n}{n}=\bar{x}+3$

$+3$ بلا وحدة قياس

مثلاً متوسط $(2,4)$ هو 3، ومتوسط $(5,7)$ هو 6؛ الفرق 3.

لا تضرب المتوسط في الثابت عند إضافته.$mw$,$mw$Adding a constant to every value shifts the mean by that constant.

$\overline{x+c}=\bar{x}+c$

1. Let the observations be $x_1,\ldots,x_n$ with $n>0$. The original mean is their sum divided by $n$.

2. Adding 3 to every observation adds a total of $3n$ to the sum.

3. Dividing by $n$ gives a mean increase of $3n/n=3$.

$\frac{\sum x_i+3n}{n}=\bar{x}+3$

$+3$ Dimensionless

For example, $(2,4)$ has mean 3 and $(5,7)$ has mean 6; the difference is 3.

Do not multiply the mean when a constant is added.$mw$),
(607,432,$mw$DA2D9CEF3179AB3DBA7D011FC3DA22E4084243BE2A23D9EDB2D16876A58A3A78$mw$,$mw$25e8f4452e61efbc3990a39e4ffc4190$mw$,$mw$$mw$,$mw${"Id":432,"StageId":2,"CategoryId":22,"Points":10,"TitleAr":"تحديد الوسيط لعدد فردي من المشاهدات","TitleEn":"Identify the median of an odd-sized data set","QuestionTextAr":"ما وسيط البيانات المرتبة: 1، 4، 7، 9، 12؟","QuestionTextEn":"What is the median of the sorted values 1, 4, 7, 9, 12?","DetailedSolutionAr":"المبدأ المستخدم: الوسيط هو القيمة الوسطى بعد ترتيب البيانات. لدينا خمس قيم مرتبة 1، 4، 7، 9، 12؛ رتبة الوسيط = (5 + 1) ÷ 2 = 3. العدد الثالث هو 7، إذن الوسيط 7، وليس متوسط القيم كلها.","DetailedSolutionEn":"Rule used: The median is the middle observation in sorted order. For 1, 4, 7, 9, 12 there are five values, so median position = (5 + 1) ÷ 2 = 3. The third value is 7; the median is 7.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":1717,"Order":1,"LatexCode":"9","IsCorrect":false},{"Id":1718,"Order":2,"LatexCode":"6","IsCorrect":false},{"Id":1719,"Order":3,"LatexCode":"7","IsCorrect":true},{"Id":1720,"Order":4,"LatexCode":"4","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"البيانات مرتبة بالفعل.","En":"The data are already sorted."},{"Ar":"حدّد رتبة الوسط ثم اقرأ القيمة في تلك الرتبة.","En":"Find the middle position and read its value."}],"Title":{"Ar":"تحديد الوسيط لعدد فردي من المشاهدات","En":"Identify the median of an odd-sized data set"},"Points":10,"Options":[{"Reason":{"Ar":"9 هي القيمة الرابعة وليست الوسطى.","En":"9 is the fourth value, not the middle one."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"9"},{"Reason":{"Ar":"6 ليست القيمة الثالثة ولا تظهر في القائمة المرتبة.","En":"6 is not the third value and does not occur in the sorted list."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"6"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"7"},{"Reason":{"Ar":"4 هي القيمة الثانية لا الثالثة.","En":"4 is second, not third."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"4"}],"StageId":2,"Question":{"Ar":"ما وسيط البيانات المرتبة: 1، 4، 7، 9، 12؟","En":"What is the median of the sorted values 1, 4, 7, 9, 12?"},"Solution":{"Idea":{"Ar":"إذا كان عدد القيم المرتبة فردياً وموجباً، فالوسيط هو القيمة التي تقع في المنتصف.","En":"If the number of sorted values is positive and odd, the median is the middle value."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"عدد القيم المرتبة 5 وهو عدد فردي.","En":"There are five sorted values, an odd count."},{"Ar":"رتبة الوسيط هي $(5+1)/2=3$.","En":"The middle position is $(5+1)/2=3$."},{"Ar":"القيمة الثالثة في القائمة هي 7.","En":"The third value in the list is 7."}],"Result":{"Ar":"$7$","En":"$7$"},"CommonError":{"Ar":"لا تحسب المتوسط بدلاً من الوسيط.","En":"Do not substitute the mean for the median."},"FormulaLatex":"M=x_{(n+1)/2}\\quad(n\\text{ odd})","Substitution":{"Ar":"$(5+1)/2=3,\\quad x_3=7$","En":"$(5+1)/2=3,\\quad x_3=7$"},"Verification":{"Ar":"يوجد عددان قبل 7 وعددان بعده.","En":"Two values precede 7 and two follow it."}},"TrackIds":[7],"CategoryId":22,"PrimarySkillId":99,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"البيانات مرتبة بالفعل.","En":"The data are already sorted."},{"Ar":"حدّد رتبة الوسط ثم اقرأ القيمة في تلك الرتبة.","En":"Find the middle position and read its value."}],"Solution":{"Idea":{"Ar":"إذا كان عدد القيم المرتبة فردياً وموجباً، فالوسيط هو القيمة التي تقع في المنتصف.","En":"If the number of sorted values is positive and odd, the median is the middle value."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"عدد القيم المرتبة 5 وهو عدد فردي.","En":"There are five sorted values, an odd count."},{"Ar":"رتبة الوسيط هي $(5+1)/2=3$.","En":"The middle position is $(5+1)/2=3$."},{"Ar":"القيمة الثالثة في القائمة هي 7.","En":"The third value in the list is 7."}],"Result":{"Ar":"$7$","En":"$7$"},"CommonError":{"Ar":"لا تحسب المتوسط بدلاً من الوسيط.","En":"Do not substitute the mean for the median."},"FormulaLatex":"M=x_{(n+1)/2}\\quad(n\\text{ odd})","Substitution":{"Ar":"$(5+1)/2=3,\\quad x_3=7$","En":"$(5+1)/2=3,\\quad x_3=7$"},"Verification":{"Ar":"يوجد عددان قبل 7 وعددان بعده.","En":"Two values precede 7 and two follow it."}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"9 هي القيمة الرابعة وليست الوسطى.","En":"9 is the fourth value, not the middle one."},"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"6 ليست القيمة الثالثة ولا تظهر في القائمة المرتبة.","En":"6 is not the third value and does not occur in the sorted list."},"Order":2},{"ErrorType":"","Reason":null,"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"4 هي القيمة الثانية لا الثالثة.","En":"4 is second, not third."},"Order":4}]}$mw$,$mw$إذا كان عدد القيم المرتبة فردياً وموجباً، فالوسيط هو القيمة التي تقع في المنتصف.

$M=x_{(n+1)/2}\quad(n\text{ odd})$

1. عدد القيم المرتبة 5 وهو عدد فردي.

2. رتبة الوسيط هي $(5+1)/2=3$.

3. القيمة الثالثة في القائمة هي 7.

$(5+1)/2=3,\quad x_3=7$

$7$ بلا وحدة قياس

يوجد عددان قبل 7 وعددان بعده.

لا تحسب المتوسط بدلاً من الوسيط.$mw$,$mw$If the number of sorted values is positive and odd, the median is the middle value.

$M=x_{(n+1)/2}\quad(n\text{ odd})$

1. There are five sorted values, an odd count.

2. The middle position is $(5+1)/2=3$.

3. The third value in the list is 7.

$(5+1)/2=3,\quad x_3=7$

$7$ Dimensionless

Two values precede 7 and two follow it.

Do not substitute the mean for the median.$mw$),
(608,433,$mw$6B699F5BFFB13C278F096261FA62CAD89301D6E80EE130488AD47CD0F9DEE285$mw$,$mw$1ede5bfa71445006be0c11ec6e45c952$mw$,$mw$$mw$,$mw${"Id":433,"StageId":2,"CategoryId":22,"Points":10,"TitleAr":"حساب المدى وتمييز أثر القيم المتطرفة","TitleEn":"Find a data range with an outlier present","QuestionTextAr":"احسب مدى القيم: 3، 4، 6، 9، 20.","QuestionTextEn":"Find the range of the values 3, 4, 6, 9, 20.","DetailedSolutionAr":"القانون المستخدم: المدى = أكبر مشاهدة − أصغر مشاهدة. في القيم 3، 4، 6، 9، 20، أكبر قيمة 20 وأصغرها 3. بالتعويض: المدى = 20 − 3 = 17. لا نجمع القيم لأن المدى يقيس الانتشار بين الطرفين.","DetailedSolutionEn":"Rule used: Range = maximum observation − minimum observation. For 3, 4, 6, 9, 20 the maximum is 20 and the minimum is 3. Hence range = 20 − 3 = 17; we do not add the values.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":1721,"Order":1,"LatexCode":"14","IsCorrect":false},{"Id":1722,"Order":2,"LatexCode":"16","IsCorrect":false},{"Id":1723,"Order":3,"LatexCode":"20","IsCorrect":false},{"Id":1724,"Order":4,"LatexCode":"17","IsCorrect":true}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"حدّد القيمتين الطرفيتين.","En":"Identify the two extreme values."},{"Ar":"اطرح القيمة الصغرى من الكبرى.","En":"Subtract the minimum from the maximum."}],"Title":{"Ar":"حساب المدى وتمييز أثر القيم المتطرفة","En":"Find a data range with an outlier present"},"Points":10,"Options":[{"Reason":{"Ar":"14 ينتج من طرح القيمة 6 بدلاً من الحد الأدنى 3.","En":"14 subtracts 6 instead of the minimum 3."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"14"},{"Reason":{"Ar":"16 ينتج من طرح 4 بدلاً من 3.","En":"16 subtracts 4 instead of 3."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"16"},{"Reason":{"Ar":"20 أكبر قيمة وليست الفرق بين الطرفين.","En":"20 is the maximum, not the difference between extremes."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"20"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"17"}],"StageId":2,"Question":{"Ar":"احسب مدى القيم: 3، 4، 6، 9، 20.","En":"Find the range of the values 3, 4, 6, 9, 20."},"Solution":{"Idea":{"Ar":"المدى هو الفرق بين أكبر وأصغر قيمة.","En":"Range is the largest value minus the smallest."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"أصغر قيمة في القائمة 3، وأكبرها 20.","En":"The smallest value is 3 and the largest is 20."},{"Ar":"نحسب الفرق $20-3=17$.","En":"Subtract $20-3=17$."}],"Result":{"Ar":"$17$","En":"$17$"},"CommonError":{"Ar":"أكبر قيمة وحدها ليست المدى.","En":"The maximum alone is not the range."},"FormulaLatex":"R=x_{\\max}-x_{\\min}","Substitution":{"Ar":"$20-3=17$","En":"$20-3=17$"},"Verification":{"Ar":"$3+17=20$","En":"$3+17=20$"}},"TrackIds":[7],"CategoryId":22,"PrimarySkillId":98,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"حدّد القيمتين الطرفيتين.","En":"Identify the two extreme values."},{"Ar":"اطرح القيمة الصغرى من الكبرى.","En":"Subtract the minimum from the maximum."}],"Solution":{"Idea":{"Ar":"المدى هو الفرق بين أكبر وأصغر قيمة.","En":"Range is the largest value minus the smallest."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"أصغر قيمة في القائمة 3، وأكبرها 20.","En":"The smallest value is 3 and the largest is 20."},{"Ar":"نحسب الفرق $20-3=17$.","En":"Subtract $20-3=17$."}],"Result":{"Ar":"$17$","En":"$17$"},"CommonError":{"Ar":"أكبر قيمة وحدها ليست المدى.","En":"The maximum alone is not the range."},"FormulaLatex":"R=x_{\\max}-x_{\\min}","Substitution":{"Ar":"$20-3=17$","En":"$20-3=17$"},"Verification":{"Ar":"$3+17=20$","En":"$3+17=20$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"14 ينتج من طرح القيمة 6 بدلاً من الحد الأدنى 3.","En":"14 subtracts 6 instead of the minimum 3."},"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"16 ينتج من طرح 4 بدلاً من 3.","En":"16 subtracts 4 instead of 3."},"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"20 أكبر قيمة وليست الفرق بين الطرفين.","En":"20 is the maximum, not the difference between extremes."},"Order":3},{"ErrorType":"","Reason":null,"Order":4}]}$mw$,$mw$المدى هو الفرق بين أكبر وأصغر قيمة.

$R=x_{\max}-x_{\min}$

1. أصغر قيمة في القائمة 3، وأكبرها 20.

2. نحسب الفرق $20-3=17$.

$20-3=17$

$17$ بلا وحدة قياس

$3+17=20$

أكبر قيمة وحدها ليست المدى.$mw$,$mw$Range is the largest value minus the smallest.

$R=x_{\max}-x_{\min}$

1. The smallest value is 3 and the largest is 20.

2. Subtract $20-3=17$.

$20-3=17$

$17$ Dimensionless

$3+17=20$

The maximum alone is not the range.$mw$),
(609,434,$mw$F34808F431EB81CB99D02B41DBCDF96FCF0BE1F06A76804A642F8F753AE6C039$mw$,$mw$58614e6f0d4a82937bf73c4c9a31640b$mw$,$mw$$mw$,$mw${"Id":434,"StageId":2,"CategoryId":22,"Points":10,"TitleAr":"تحويل التكرار النسبي إلى نسبة مئوية","TitleEn":"Express relative frequency as a percentage","QuestionTextAr":"من أصل 20 استجابة في استبيان، اختار 5 طلاب خياراً معيناً. ما التكرار النسبي بالنسبة المئوية؟","QuestionTextEn":"In a survey with 20 responses, 5 select one option. What is the relative frequency as a percentage?","DetailedSolutionAr":"القانون المستخدم: التكرار النسبي المئوي = عدد استجابات الفئة ÷ إجمالي الاستجابات × 100%. لدينا 5 استجابات من 20؛ نحسب 5 ÷ 20 = 1/4 = 0.25، ثم 0.25 × 100% = 25%. إذن التكرار النسبي 25%.","DetailedSolutionEn":"Rule used: Relative frequency as a percentage = category count ÷ total responses × 100%. With 5 out of 20, calculate 5 ÷ 20 = 1/4 = 0.25; then 0.25 × 100% = 25%. Answer: 25%.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":1725,"Order":1,"LatexCode":"40\\%","IsCorrect":false},{"Id":1726,"Order":2,"LatexCode":"25\\%","IsCorrect":true},{"Id":1727,"Order":3,"LatexCode":"5\\%","IsCorrect":false},{"Id":1728,"Order":4,"LatexCode":"20\\%","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"ميّز تكرار الخيار عن العدد الكلي.","En":"Distinguish the option frequency from the total."},{"Ar":"اقسم تكرار الخيار على الإجمالي ثم حوّل إلى نسبة مئوية.","En":"Divide by the total and convert to a percentage."}],"Title":{"Ar":"تحويل التكرار النسبي إلى نسبة مئوية","En":"Express relative frequency as a percentage"},"Points":10,"Options":[{"Reason":{"Ar":"40% من 20 يساوي 8 لا 5.","En":"40% of 20 is 8, not 5."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"40\\%"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"25\\%"},{"Reason":{"Ar":"5 هو التكرار الخام؛ 5% من 20 يساوي 1.","En":"5 is the raw frequency; 5% of 20 is 1."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"5\\%"},{"Reason":{"Ar":"20% من 20 يساوي 4 لا 5.","En":"20% of 20 is 4, not 5."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"20\\%"}],"StageId":2,"Question":{"Ar":"من أصل 20 استجابة في استبيان، اختار 5 طلاب خياراً معيناً. ما التكرار النسبي بالنسبة المئوية؟","En":"In a survey with 20 responses, 5 select one option. What is the relative frequency as a percentage?"},"Solution":{"Idea":{"Ar":"حيث $f$ تكرار الخيار و$N$ عدد الاستجابات الكلي الموجب؛ نضرب النسبة في 100 لتمثيلها مئوياً.","En":"Here $f$ is the option frequency and $N$ is the positive total response count; express their ratio per hundred."},"Unit":{"Ar":"نسبة مئوية","En":"Percent"},"Steps":[{"Ar":"تكرار الخيار 5 والإجمالي 20 استجابة.","En":"The option has frequency 5 and there are 20 responses in total."},{"Ar":"نقسم $5/20=1/4=0.25$.","En":"Divide $5/20=1/4=0.25$."},{"Ar":"نحوّل إلى نسبة مئوية: $0.25\\times100\\%=25\\%$.","En":"Convert to a percentage: $0.25\\times100\\%=25\\%$."}],"Result":{"Ar":"$25\\%$","En":"$25\\%$"},"CommonError":{"Ar":"لا تعتبر العدد الخام نسبة مئوية.","En":"Do not mistake the raw count for a percentage."},"FormulaLatex":"p=\\frac{f}{N}\\times100\\%,\\quad N>0","Substitution":{"Ar":"$\\frac5{20}\\times100\\%=25\\%$","En":"$\\frac5{20}\\times100\\%=25\\%$"},"Verification":{"Ar":"$20\\times0.25=5$","En":"$20\\times0.25=5$"}},"TrackIds":[7],"CategoryId":22,"PrimarySkillId":100,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"ميّز تكرار الخيار عن العدد الكلي.","En":"Distinguish the option frequency from the total."},{"Ar":"اقسم تكرار الخيار على الإجمالي ثم حوّل إلى نسبة مئوية.","En":"Divide by the total and convert to a percentage."}],"Solution":{"Idea":{"Ar":"حيث $f$ تكرار الخيار و$N$ عدد الاستجابات الكلي الموجب؛ نضرب النسبة في 100 لتمثيلها مئوياً.","En":"Here $f$ is the option frequency and $N$ is the positive total response count; express their ratio per hundred."},"Unit":{"Ar":"نسبة مئوية","En":"Percent"},"Steps":[{"Ar":"تكرار الخيار 5 والإجمالي 20 استجابة.","En":"The option has frequency 5 and there are 20 responses in total."},{"Ar":"نقسم $5/20=1/4=0.25$.","En":"Divide $5/20=1/4=0.25$."},{"Ar":"نحوّل إلى نسبة مئوية: $0.25\\times100\\%=25\\%$.","En":"Convert to a percentage: $0.25\\times100\\%=25\\%$."}],"Result":{"Ar":"$25\\%$","En":"$25\\%$"},"CommonError":{"Ar":"لا تعتبر العدد الخام نسبة مئوية.","En":"Do not mistake the raw count for a percentage."},"FormulaLatex":"p=\\frac{f}{N}\\times100\\%,\\quad N>0","Substitution":{"Ar":"$\\frac5{20}\\times100\\%=25\\%$","En":"$\\frac5{20}\\times100\\%=25\\%$"},"Verification":{"Ar":"$20\\times0.25=5$","En":"$20\\times0.25=5$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"40% من 20 يساوي 8 لا 5.","En":"40% of 20 is 8, not 5."},"Order":1},{"ErrorType":"","Reason":null,"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"5 هو التكرار الخام؛ 5% من 20 يساوي 1.","En":"5 is the raw frequency; 5% of 20 is 1."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"20% من 20 يساوي 4 لا 5.","En":"20% of 20 is 4, not 5."},"Order":4}]}$mw$,$mw$حيث $f$ تكرار الخيار و$N$ عدد الاستجابات الكلي الموجب؛ نضرب النسبة في 100 لتمثيلها مئوياً.

$p=\frac{f}{N}\times100\%,\quad N>0$

1. تكرار الخيار 5 والإجمالي 20 استجابة.

2. نقسم $5/20=1/4=0.25$.

3. نحوّل إلى نسبة مئوية: $0.25\times100\%=25\%$.

$\frac5{20}\times100\%=25\%$

$25\%$ نسبة مئوية

$20\times0.25=5$

لا تعتبر العدد الخام نسبة مئوية.$mw$,$mw$Here $f$ is the option frequency and $N$ is the positive total response count; express their ratio per hundred.

$p=\frac{f}{N}\times100\%,\quad N>0$

1. The option has frequency 5 and there are 20 responses in total.

2. Divide $5/20=1/4=0.25$.

3. Convert to a percentage: $0.25\times100\%=25\%$.

$\frac5{20}\times100\%=25\%$

$25\%$ Percent

$20\times0.25=5$

Do not mistake the raw count for a percentage.$mw$),
(610,435,$mw$A90BC460E556803C150CB4D60CFDDA6E21AF5D9D57B21142DE27DD149A298858$mw$,$mw$13960f526380d7131f93f8a79c8a5ccc$mw$,$mw$$mw$,$mw${"Id":435,"StageId":2,"CategoryId":22,"Points":10,"TitleAr":"حساب متوسط من جدول تكراري","TitleEn":"Compute a mean from a frequency description","QuestionTextAr":"ظهرت القيمة 2 ثلاث مرات والقيمة 7 مرتين في مجموعة بيانات. ما المتوسط الحسابي؟","QuestionTextEn":"In a data set, 2 appears three times and 7 appears twice. What is the mean?","DetailedSolutionAr":"القانون المستخدم: المتوسط المرجح بالتكرارات = مجموع (القيمة × تكرارها) ÷ مجموع التكرارات. العدد 2 يتكرر 3 مرات والعدد 7 مرتين؛ المجموع = 2 × 3 + 7 × 2 = 6 + 14 = 20. عدد المشاهدات = 3 + 2 = 5. المتوسط = 20 ÷ 5 = 4.","DetailedSolutionEn":"Rule used: Frequency-weighted mean = sum(value × frequency) ÷ total frequency. The value 2 occurs 3 times and 7 occurs twice, giving sum 2 × 3 + 7 × 2 = 20. There are 5 observations, so mean = 20 ÷ 5 = 4.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":1729,"Order":1,"LatexCode":"4.5","IsCorrect":false},{"Id":1730,"Order":2,"LatexCode":"5","IsCorrect":false},{"Id":1731,"Order":3,"LatexCode":"3","IsCorrect":false},{"Id":1732,"Order":4,"LatexCode":"4","IsCorrect":true}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"انتبه إلى عدد مرات تكرار كل قيمة.","En":"Notice how often each value occurs."},{"Ar":"اضرب كل قيمة في تكرارها واجمع ثم اقسم على مجموع التكرارات.","En":"Multiply each value by its frequency, sum, then divide by total frequency."}],"Title":{"Ar":"حساب متوسط من جدول تكراري","En":"Compute a mean from a frequency description"},"Points":10,"Options":[{"Reason":{"Ar":"$4.5=(2+7)/2$ يهمل اختلاف التكرارين.","En":"$4.5=(2+7)/2$ ignores the unequal frequencies."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"4.5"},{"Reason":{"Ar":"5 عدد المشاهدات، ولو كان متوسطها 5 لكان مجموعها 25 لا 20.","En":"5 is the count; if it were the mean, the sum would be 25, not 20."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"5"},{"Reason":{"Ar":"المتوسط 3 يتطلب مجموعاً 15 لخمس مشاهدات لا 20.","En":"A mean of 3 for five observations would require a sum of 15, not 20."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"3"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"4"}],"StageId":2,"Question":{"Ar":"ظهرت القيمة 2 ثلاث مرات والقيمة 7 مرتين في مجموعة بيانات. ما المتوسط الحسابي؟","En":"In a data set, 2 appears three times and 7 appears twice. What is the mean?"},"Solution":{"Idea":{"Ar":"تكرار القيمة $x_i$ هو $f_i$؛ لذلك تدخل القيمة في المجموع بعدد مرات ظهورها.","En":"The frequency of value $x_i$ is $f_i$, so each value contributes once per occurrence."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"القيمة 2 تسهم بمجموع $2\\times3=6$، والقيمة 7 تسهم بمجموع $7\\times2=14$.","En":"The value 2 contributes $2\\times3=6$ and the value 7 contributes $7\\times2=14$."},{"Ar":"مجموع المشاهدات $6+14=20$ وعددها $3+2=5$.","En":"The observation sum is $6+14=20$ and the count is $3+2=5$."},{"Ar":"المتوسط $20/5=4$.","En":"The mean is $20/5=4$."}],"Result":{"Ar":"$4$","En":"$4$"},"CommonError":{"Ar":"لا تأخذ متوسط القيمتين المتميزتين فقط.","En":"Do not average only the two distinct values."},"FormulaLatex":"\\bar x=\\frac{\\sum_i f_i x_i}{\\sum_i f_i},\\quad\\sum_i f_i>0","Substitution":{"Ar":"$\\frac{3\\times2+2\\times7}{3+2}=\\frac{20}{5}=4$","En":"$\\frac{3\\times2+2\\times7}{3+2}=\\frac{20}{5}=4$"},"Verification":{"Ar":"$4\\times5=20$","En":"$4\\times5=20$"}},"TrackIds":[8],"CategoryId":22,"PrimarySkillId":99,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"انتبه إلى عدد مرات تكرار كل قيمة.","En":"Notice how often each value occurs."},{"Ar":"اضرب كل قيمة في تكرارها واجمع ثم اقسم على مجموع التكرارات.","En":"Multiply each value by its frequency, sum, then divide by total frequency."}],"Solution":{"Idea":{"Ar":"تكرار القيمة $x_i$ هو $f_i$؛ لذلك تدخل القيمة في المجموع بعدد مرات ظهورها.","En":"The frequency of value $x_i$ is $f_i$, so each value contributes once per occurrence."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"القيمة 2 تسهم بمجموع $2\\times3=6$، والقيمة 7 تسهم بمجموع $7\\times2=14$.","En":"The value 2 contributes $2\\times3=6$ and the value 7 contributes $7\\times2=14$."},{"Ar":"مجموع المشاهدات $6+14=20$ وعددها $3+2=5$.","En":"The observation sum is $6+14=20$ and the count is $3+2=5$."},{"Ar":"المتوسط $20/5=4$.","En":"The mean is $20/5=4$."}],"Result":{"Ar":"$4$","En":"$4$"},"CommonError":{"Ar":"لا تأخذ متوسط القيمتين المتميزتين فقط.","En":"Do not average only the two distinct values."},"FormulaLatex":"\\bar x=\\frac{\\sum_i f_i x_i}{\\sum_i f_i},\\quad\\sum_i f_i>0","Substitution":{"Ar":"$\\frac{3\\times2+2\\times7}{3+2}=\\frac{20}{5}=4$","En":"$\\frac{3\\times2+2\\times7}{3+2}=\\frac{20}{5}=4$"},"Verification":{"Ar":"$4\\times5=20$","En":"$4\\times5=20$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"$4.5=(2+7)/2$ يهمل اختلاف التكرارين.","En":"$4.5=(2+7)/2$ ignores the unequal frequencies."},"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"5 عدد المشاهدات، ولو كان متوسطها 5 لكان مجموعها 25 لا 20.","En":"5 is the count; if it were the mean, the sum would be 25, not 20."},"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"المتوسط 3 يتطلب مجموعاً 15 لخمس مشاهدات لا 20.","En":"A mean of 3 for five observations would require a sum of 15, not 20."},"Order":3},{"ErrorType":"","Reason":null,"Order":4}]}$mw$,$mw$تكرار القيمة $x_i$ هو $f_i$؛ لذلك تدخل القيمة في المجموع بعدد مرات ظهورها.

$\bar x=\frac{\sum_i f_i x_i}{\sum_i f_i},\quad\sum_i f_i>0$

1. القيمة 2 تسهم بمجموع $2\times3=6$، والقيمة 7 تسهم بمجموع $7\times2=14$.

2. مجموع المشاهدات $6+14=20$ وعددها $3+2=5$.

3. المتوسط $20/5=4$.

$\frac{3\times2+2\times7}{3+2}=\frac{20}{5}=4$

$4$ بلا وحدة قياس

$4\times5=20$

لا تأخذ متوسط القيمتين المتميزتين فقط.$mw$,$mw$The frequency of value $x_i$ is $f_i$, so each value contributes once per occurrence.

$\bar x=\frac{\sum_i f_i x_i}{\sum_i f_i},\quad\sum_i f_i>0$

1. The value 2 contributes $2\times3=6$ and the value 7 contributes $7\times2=14$.

2. The observation sum is $6+14=20$ and the count is $3+2=5$.

3. The mean is $20/5=4$.

$\frac{3\times2+2\times7}{3+2}=\frac{20}{5}=4$

$4$ Dimensionless

$4\times5=20$

Do not average only the two distinct values.$mw$),
(611,436,$mw$014DEF1C7DAE4FAA833183A878B4A89105F578BD6CDFEF6EAC05DAC392A2542F$mw$,$mw$50a13d12df535b4d9172c4e3a6c47e0b$mw$,$mw$$mw$,$mw${"Id":436,"StageId":3,"CategoryId":23,"Points":10,"TitleAr":"استخلاص الصيغة العامة لمتتالية حسابية","TitleEn":"Derive the nth-term rule for an arithmetic progression","QuestionTextAr":"المتتالية $5,9,13,17,\\ldots$ حسابية. أي صيغة تعطي الحد $a_n$ إذا بدأنا من $n=1$؟","QuestionTextEn":"The arithmetic sequence is $5,9,13,17,\\ldots$. Which formula gives $a_n$ starting at $n=1$?","DetailedSolutionAr":"قانون الحد النوني للمتتالية الحسابية: أₙ = أ₁ + (ن − 1)د. المتتالية 5، 9، 13، 17 لها حد أول أ₁ = 5 وفرق مشترك د = 9 − 5 = 4. بالتعويض: أₙ = 5 + 4(ن − 1) = 5 + 4ن − 4 = 4ن + 1. التحقق عند ن = 1 يعطي 5 وعند ن = 2 يعطي 9.","DetailedSolutionEn":"Arithmetic sequence nth-term rule: a_n = a₁ + (n−1)d. The first term is 5 and common difference is 9 − 5 = 4. Substitute: a_n = 5 + 4(n−1) = 5 + 4n − 4 = 4n + 1. Check: at n=1 gives 5, at n=2 gives 9.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":1733,"Order":1,"LatexCode":"4n+1","IsCorrect":true},{"Id":1734,"Order":2,"LatexCode":"5n+4","IsCorrect":false},{"Id":1735,"Order":3,"LatexCode":"4n-1","IsCorrect":false},{"Id":1736,"Order":4,"LatexCode":"n+4","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"حدد الحد الأول والفرق المشترك.","En":"Identify the first term and common difference."},{"Ar":"استعمل صيغة الحد العام بدءاً من n=1 ثم بسّط.","En":"Use the nth-term formula beginning at n=1, then simplify."}],"Title":{"Ar":"استخلاص الصيغة العامة لمتتالية حسابية","En":"Derive the nth-term rule for an arithmetic progression"},"Points":10,"Options":[{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"4n+1"},{"Reason":{"Ar":"عند n=1 يعطي 9 لا 5، كما أن الفرق يصبح 5.","En":"At n=1 this gives 9 instead of 5, and the difference is 5."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"5n+4"},{"Reason":{"Ar":"عند n=1 يعطي 3 لا 5 رغم صحة معامل الزيادة.","En":"At n=1 it gives 3 rather than 5 despite the correct step coefficient."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"4n-1"},{"Reason":{"Ar":"يبدأ بـ5 لكن يزيد بمقدار 1 لا 4.","En":"It starts at 5 but increases by 1 rather than 4."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"n+4"}],"StageId":3,"Question":{"Ar":"المتتالية $5,9,13,17,\\ldots$ حسابية. أي صيغة تعطي الحد $a_n$ إذا بدأنا من $n=1$؟","En":"The arithmetic sequence is $5,9,13,17,\\ldots$. Which formula gives $a_n$ starting at $n=1$?"},"Solution":{"Idea":{"Ar":"المتتالية الحسابية لها فرق ثابت بين كل حدين متتاليين.","En":"An arithmetic sequence has a constant difference between successive terms."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"الفرق المشترك $d=9-5=4$؛ والفروق التالية تساوي 4 أيضاً.","En":"The common difference is $d=9-5=4$, and subsequent differences are also 4."},{"Ar":"بما أن $a_1=5$ و$n\\ge1$، نكتب $a_n=5+4(n-1)$.","En":"Since $a_1=5$ and $n\\ge1$, write $a_n=5+4(n-1)$."},{"Ar":"نوزع ثم نجمع الثوابت: $5+4n-4=4n+1$.","En":"Expand and combine constants: $5+4n-4=4n+1$."}],"Result":{"Ar":"$4n+1$","En":"$4n+1$"},"CommonError":{"Ar":"لا تضرب الفرق في n بدلاً من n−1 دون ضبط الحد الأول.","En":"Do not multiply the difference by n instead of n−1 without adjusting the first term."},"FormulaLatex":"a_n=a_1+(n-1)d","Substitution":{"Ar":"$d=9-5=4,\\quad a_n=5+4(n-1)=4n+1$","En":"$d=9-5=4,\\quad a_n=5+4(n-1)=4n+1$"},"Verification":{"Ar":"$a_1=5,\\quad a_2=9$","En":"$a_1=5,\\quad a_2=9$"}},"TrackIds":[10],"CategoryId":23,"PrimarySkillId":104,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"حدد الحد الأول والفرق المشترك.","En":"Identify the first term and common difference."},{"Ar":"استعمل صيغة الحد العام بدءاً من n=1 ثم بسّط.","En":"Use the nth-term formula beginning at n=1, then simplify."}],"Solution":{"Idea":{"Ar":"المتتالية الحسابية لها فرق ثابت بين كل حدين متتاليين.","En":"An arithmetic sequence has a constant difference between successive terms."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"الفرق المشترك $d=9-5=4$؛ والفروق التالية تساوي 4 أيضاً.","En":"The common difference is $d=9-5=4$, and subsequent differences are also 4."},{"Ar":"بما أن $a_1=5$ و$n\\ge1$، نكتب $a_n=5+4(n-1)$.","En":"Since $a_1=5$ and $n\\ge1$, write $a_n=5+4(n-1)$."},{"Ar":"نوزع ثم نجمع الثوابت: $5+4n-4=4n+1$.","En":"Expand and combine constants: $5+4n-4=4n+1$."}],"Result":{"Ar":"$4n+1$","En":"$4n+1$"},"CommonError":{"Ar":"لا تضرب الفرق في n بدلاً من n−1 دون ضبط الحد الأول.","En":"Do not multiply the difference by n instead of n−1 without adjusting the first term."},"FormulaLatex":"a_n=a_1+(n-1)d","Substitution":{"Ar":"$d=9-5=4,\\quad a_n=5+4(n-1)=4n+1$","En":"$d=9-5=4,\\quad a_n=5+4(n-1)=4n+1$"},"Verification":{"Ar":"$a_1=5,\\quad a_2=9$","En":"$a_1=5,\\quad a_2=9$"}},"Distractors":[{"ErrorType":"","Reason":null,"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"عند n=1 يعطي 9 لا 5، كما أن الفرق يصبح 5.","En":"At n=1 this gives 9 instead of 5, and the difference is 5."},"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"عند n=1 يعطي 3 لا 5 رغم صحة معامل الزيادة.","En":"At n=1 it gives 3 rather than 5 despite the correct step coefficient."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"يبدأ بـ5 لكن يزيد بمقدار 1 لا 4.","En":"It starts at 5 but increases by 1 rather than 4."},"Order":4}]}$mw$,$mw$المتتالية الحسابية لها فرق ثابت بين كل حدين متتاليين.

$a_n=a_1+(n-1)d$

1. الفرق المشترك $d=9-5=4$؛ والفروق التالية تساوي 4 أيضاً.

2. بما أن $a_1=5$ و$n\ge1$، نكتب $a_n=5+4(n-1)$.

3. نوزع ثم نجمع الثوابت: $5+4n-4=4n+1$.

$d=9-5=4,\quad a_n=5+4(n-1)=4n+1$

$4n+1$ بلا وحدة قياس

$a_1=5,\quad a_2=9$

لا تضرب الفرق في n بدلاً من n−1 دون ضبط الحد الأول.$mw$,$mw$An arithmetic sequence has a constant difference between successive terms.

$a_n=a_1+(n-1)d$

1. The common difference is $d=9-5=4$, and subsequent differences are also 4.

2. Since $a_1=5$ and $n\ge1$, write $a_n=5+4(n-1)$.

3. Expand and combine constants: $5+4n-4=4n+1$.

$d=9-5=4,\quad a_n=5+4(n-1)=4n+1$

$4n+1$ Dimensionless

$a_1=5,\quad a_2=9$

Do not multiply the difference by n instead of n−1 without adjusting the first term.$mw$),
(612,437,$mw$52B83D09DA33B4015D4A29DF2B05C6C4AF4CCEA26BECC986DB03325A67918F38$mw$,$mw$aa250bbe5568bcb97a737c680cc5136d$mw$,$mw$$mw$,$mw${"Id":437,"StageId":3,"CategoryId":23,"Points":10,"TitleAr":"حساب حد من متتالية هندسية باستخدام النسبة","TitleEn":"Find a geometric term using its common ratio","QuestionTextAr":"متتالية هندسية حدها الأول 3 ونسبتها المشتركة 2. ما الحد الخامس؟","QuestionTextEn":"A geometric sequence has first term 3 and common ratio 2. What is its fifth term?","DetailedSolutionAr":"هذه متتالية هندسية حدها الأول $a_1=3$ ونسبتها المشتركة $r=2$. قانون الحد العام $a_n=a_1r^{n-1}$، ولذلك $a_5=3\\times2^4=48$.","DetailedSolutionEn":"This is a geometric sequence with first term $a_1=3$ and common ratio $r=2$. Using $a_n=a_1r^{n-1}$ gives $a_5=3\\times2^4=48$.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":1737,"Order":1,"LatexCode":"96","IsCorrect":false},{"Id":1738,"Order":2,"LatexCode":"32","IsCorrect":false},{"Id":1739,"Order":3,"LatexCode":"48","IsCorrect":true},{"Id":1740,"Order":4,"LatexCode":"24","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"استعمل الحد الأول والنسبة المشتركة.","En":"Use the first term and common ratio."},{"Ar":"حدد عدد مرات الضرب اللازمة للانتقال من الحد الأول إلى الخامس.","En":"Determine the number of multiplications from the first term to the fifth."}],"Title":{"Ar":"حساب حد من متتالية هندسية باستخدام النسبة","En":"Find a geometric term using its common ratio"},"Points":10,"Options":[{"Reason":{"Ar":"96 هو الحد السادس، بعد خمس ضربات لا أربع.","En":"96 is the sixth term after five multiplications, not four."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"96"},{"Reason":{"Ar":"32 لا يساوي 3 مضروباً في 16.","En":"32 is not 3 times 16."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"32"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"48"},{"Reason":{"Ar":"24 هو الحد الرابع بعد ثلاث ضربات.","En":"24 is the fourth term after three multiplications."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"24"}],"StageId":3,"Question":{"Ar":"متتالية هندسية حدها الأول 3 ونسبتها المشتركة 2. ما الحد الخامس؟","En":"A geometric sequence has first term 3 and common ratio 2. What is its fifth term?"},"Solution":{"Idea":{"Ar":"في المتتالية الهندسية كل حد ينتج من ضرب السابق في النسبة المشتركة.","En":"In a geometric sequence each term is obtained by multiplying the preceding term by the common ratio."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"من الحد الأول إلى الخامس توجد $5-1=4$ انتقالات.","En":"From the first to the fifth term there are $5-1=4$ transitions."},{"Ar":"كل انتقال يضرب الحد السابق في 2، فنحسب $3\\times2^4$.","En":"Each transition multiplies the preceding term by 2, giving $3\\times2^4$."},{"Ar":"بما أن $2^4=16$، فالحد الخامس $3\\times16=48$.","En":"Since $2^4=16$, the fifth term is $3\\times16=48$."}],"Result":{"Ar":"$48$","En":"$48$"},"CommonError":{"Ar":"لا ترفع النسبة للأس الخامس عندما يبدأ العد من الأول.","En":"Do not use the fifth power when indexing starts at one."},"FormulaLatex":"a_n=a_1r^{n-1}","Substitution":{"Ar":"$a_5=3\\times2^4=48$","En":"$a_5=3\\times2^4=48$"},"Verification":{"Ar":"$3,6,12,24,48$","En":"$3,6,12,24,48$"}},"TrackIds":[10],"CategoryId":23,"PrimarySkillId":103,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"استعمل الحد الأول والنسبة المشتركة.","En":"Use the first term and common ratio."},{"Ar":"حدد عدد مرات الضرب اللازمة للانتقال من الحد الأول إلى الخامس.","En":"Determine the number of multiplications from the first term to the fifth."}],"Solution":{"Idea":{"Ar":"في المتتالية الهندسية كل حد ينتج من ضرب السابق في النسبة المشتركة.","En":"In a geometric sequence each term is obtained by multiplying the preceding term by the common ratio."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"من الحد الأول إلى الخامس توجد $5-1=4$ انتقالات.","En":"From the first to the fifth term there are $5-1=4$ transitions."},{"Ar":"كل انتقال يضرب الحد السابق في 2، فنحسب $3\\times2^4$.","En":"Each transition multiplies the preceding term by 2, giving $3\\times2^4$."},{"Ar":"بما أن $2^4=16$، فالحد الخامس $3\\times16=48$.","En":"Since $2^4=16$, the fifth term is $3\\times16=48$."}],"Result":{"Ar":"$48$","En":"$48$"},"CommonError":{"Ar":"لا ترفع النسبة للأس الخامس عندما يبدأ العد من الأول.","En":"Do not use the fifth power when indexing starts at one."},"FormulaLatex":"a_n=a_1r^{n-1}","Substitution":{"Ar":"$a_5=3\\times2^4=48$","En":"$a_5=3\\times2^4=48$"},"Verification":{"Ar":"$3,6,12,24,48$","En":"$3,6,12,24,48$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"96 هو الحد السادس، بعد خمس ضربات لا أربع.","En":"96 is the sixth term after five multiplications, not four."},"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"32 لا يساوي 3 مضروباً في 16.","En":"32 is not 3 times 16."},"Order":2},{"ErrorType":"","Reason":null,"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"24 هو الحد الرابع بعد ثلاث ضربات.","En":"24 is the fourth term after three multiplications."},"Order":4}]}$mw$,$mw$في المتتالية الهندسية كل حد ينتج من ضرب السابق في النسبة المشتركة.

$a_n=a_1r^{n-1}$

1. من الحد الأول إلى الخامس توجد $5-1=4$ انتقالات.

2. كل انتقال يضرب الحد السابق في 2، فنحسب $3\times2^4$.

3. بما أن $2^4=16$، فالحد الخامس $3\times16=48$.

$a_5=3\times2^4=48$

$48$ بلا وحدة قياس

$3,6,12,24,48$

لا ترفع النسبة للأس الخامس عندما يبدأ العد من الأول.$mw$,$mw$In a geometric sequence each term is obtained by multiplying the preceding term by the common ratio.

$a_n=a_1r^{n-1}$

1. From the first to the fifth term there are $5-1=4$ transitions.

2. Each transition multiplies the preceding term by 2, giving $3\times2^4$.

3. Since $2^4=16$, the fifth term is $3\times16=48$.

$a_5=3\times2^4=48$

$48$ Dimensionless

$3,6,12,24,48$

Do not use the fifth power when indexing starts at one.$mw$),
(613,438,$mw$D63A6A62B4D80062B1D48A3CD93E06360FCE85501A2C2DDE84FCE432594F79F4$mw$,$mw$1c7b06ff1a44ccaeed4af4c3b7868e0b$mw$,$mw$$mw$,$mw${"Id":438,"StageId":3,"CategoryId":23,"Points":10,"TitleAr":"استنتاج الفرق المشترك من حدين غير متتاليين","TitleEn":"Infer common difference from nonadjacent terms","QuestionTextAr":"في متتالية حسابية، $a_3=11$ و$a_7=27$. ما الفرق المشترك؟","QuestionTextEn":"In an arithmetic sequence, $a_3=11$ and $a_7=27$. Find the common difference.","DetailedSolutionAr":"المبدأ المستخدم: الفرق المشترك للمتتالية الحسابية ثابت، وبين الحدين أ₃ وأ₇ توجد 7 − 3 = 4 انتقالات. لذلك أ₇ − أ₃ = 4د. بالتعويض: 27 − 11 = 4د، أي 16 = 4د، فنقسم على 4 لنحصل على د = 4. التحقق: 11 + 4 × 4 = 27.","DetailedSolutionEn":"Rule used: An arithmetic sequence has a constant common difference, and there are 7 − 3 = 4 steps between a₃ and a₇. Hence a₇ − a₃ = 4d. Substitute 27 − 11 = 4d, so 16 = 4d and d = 4. Check: 11 + 4 × 4 = 27.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":1741,"Order":1,"LatexCode":"8","IsCorrect":false},{"Id":1742,"Order":2,"LatexCode":"4","IsCorrect":true},{"Id":1743,"Order":3,"LatexCode":"3","IsCorrect":false},{"Id":1744,"Order":4,"LatexCode":"5","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"احسب فرق الرتبتين لا عدد الحدود شاملاً الطرفين.","En":"Find the index difference, not the inclusive count of terms."},{"Ar":"اقسم فرق القيمتين على فرق الرتبتين.","En":"Divide the value difference by the index difference."}],"Title":{"Ar":"استنتاج الفرق المشترك من حدين غير متتاليين","En":"Infer common difference from nonadjacent terms"},"Points":10,"Options":[{"Reason":{"Ar":"فرق 8 خلال أربع انتقالات يعطي 43 لا 27.","En":"A difference of 8 across four transitions gives 43, not 27."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"8"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"4"},{"Reason":{"Ar":"فرق 3 يعطي 23 لا 27.","En":"A difference of 3 gives 23, not 27."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"3"},{"Reason":{"Ar":"فرق 5 يعطي 31 لا 27.","En":"A difference of 5 gives 31, not 27."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"5"}],"StageId":3,"Question":{"Ar":"في متتالية حسابية، $a_3=11$ و$a_7=27$. ما الفرق المشترك؟","En":"In an arithmetic sequence, $a_3=11$ and $a_7=27$. Find the common difference."},"Solution":{"Idea":{"Ar":"فرق حدين في المتتالية الحسابية يساوي الفرق المشترك مضروباً في فرق رتبتيهما.","En":"The difference of two arithmetic-sequence terms equals the common difference times their index difference."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"من الرتبة 3 إلى الرتبة 7 توجد $7-3=4$ انتقالات متساوية.","En":"From index 3 to index 7 there are $7-3=4$ equal transitions."},{"Ar":"الزيادة الكلية $27-11=16$.","En":"The total increase is $27-11=16$."},{"Ar":"نقسم الزيادة الكلية على عدد الانتقالات: $16/4=4$.","En":"Divide the total increase by the number of transitions: $16/4=4$."}],"Result":{"Ar":"$4$","En":"$4$"},"CommonError":{"Ar":"لا تقسم على 7 أو 3 مباشرة.","En":"Do not divide by 7 or 3 directly."},"FormulaLatex":"d=\\frac{a_j-a_i}{j-i}\\quad(j\\ne i)","Substitution":{"Ar":"$\\frac{27-11}{7-3}=\\frac{16}4=4$","En":"$\\frac{27-11}{7-3}=\\frac{16}4=4$"},"Verification":{"Ar":"$11+4(7-3)=27$","En":"$11+4(7-3)=27$"}},"TrackIds":[10],"CategoryId":23,"PrimarySkillId":104,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"احسب فرق الرتبتين لا عدد الحدود شاملاً الطرفين.","En":"Find the index difference, not the inclusive count of terms."},{"Ar":"اقسم فرق القيمتين على فرق الرتبتين.","En":"Divide the value difference by the index difference."}],"Solution":{"Idea":{"Ar":"فرق حدين في المتتالية الحسابية يساوي الفرق المشترك مضروباً في فرق رتبتيهما.","En":"The difference of two arithmetic-sequence terms equals the common difference times their index difference."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"من الرتبة 3 إلى الرتبة 7 توجد $7-3=4$ انتقالات متساوية.","En":"From index 3 to index 7 there are $7-3=4$ equal transitions."},{"Ar":"الزيادة الكلية $27-11=16$.","En":"The total increase is $27-11=16$."},{"Ar":"نقسم الزيادة الكلية على عدد الانتقالات: $16/4=4$.","En":"Divide the total increase by the number of transitions: $16/4=4$."}],"Result":{"Ar":"$4$","En":"$4$"},"CommonError":{"Ar":"لا تقسم على 7 أو 3 مباشرة.","En":"Do not divide by 7 or 3 directly."},"FormulaLatex":"d=\\frac{a_j-a_i}{j-i}\\quad(j\\ne i)","Substitution":{"Ar":"$\\frac{27-11}{7-3}=\\frac{16}4=4$","En":"$\\frac{27-11}{7-3}=\\frac{16}4=4$"},"Verification":{"Ar":"$11+4(7-3)=27$","En":"$11+4(7-3)=27$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"فرق 8 خلال أربع انتقالات يعطي 43 لا 27.","En":"A difference of 8 across four transitions gives 43, not 27."},"Order":1},{"ErrorType":"","Reason":null,"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"فرق 3 يعطي 23 لا 27.","En":"A difference of 3 gives 23, not 27."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"فرق 5 يعطي 31 لا 27.","En":"A difference of 5 gives 31, not 27."},"Order":4}]}$mw$,$mw$فرق حدين في المتتالية الحسابية يساوي الفرق المشترك مضروباً في فرق رتبتيهما.

$d=\frac{a_j-a_i}{j-i}\quad(j\ne i)$

1. من الرتبة 3 إلى الرتبة 7 توجد $7-3=4$ انتقالات متساوية.

2. الزيادة الكلية $27-11=16$.

3. نقسم الزيادة الكلية على عدد الانتقالات: $16/4=4$.

$\frac{27-11}{7-3}=\frac{16}4=4$

$4$ بلا وحدة قياس

$11+4(7-3)=27$

لا تقسم على 7 أو 3 مباشرة.$mw$,$mw$The difference of two arithmetic-sequence terms equals the common difference times their index difference.

$d=\frac{a_j-a_i}{j-i}\quad(j\ne i)$

1. From index 3 to index 7 there are $7-3=4$ equal transitions.

2. The total increase is $27-11=16$.

3. Divide the total increase by the number of transitions: $16/4=4$.

$\frac{27-11}{7-3}=\frac{16}4=4$

$4$ Dimensionless

$11+4(7-3)=27$

Do not divide by 7 or 3 directly.$mw$),
(614,439,$mw$6C5802B8911C64D5B0A9B9E578E9853B4377542D2192F40F9732E38D809B3224$mw$,$mw$9524a834c62166756ae902e143d49172$mw$,$mw$$mw$,$mw${"Id":439,"StageId":3,"CategoryId":23,"Points":10,"TitleAr":"حساب حد محدد من متتالية حسابية","TitleEn":"Find a specified term of an arithmetic progression","QuestionTextAr":"متتالية حسابية حدها الأول 4 وفرقها المشترك 3. أوجد الحد العاشر.","QuestionTextEn":"An arithmetic sequence has first term 4 and common difference 3. Find the tenth term.","DetailedSolutionAr":"نستخدم قانون المتتالية الحسابية $a_n=a_1+(n-1)d$. لدينا $a_1=4$ و$d=3$، لذا $a_{10}=4+9\\times3=31$.","DetailedSolutionEn":"Use the arithmetic progression formula $a_n=a_1+(n-1)d$. With $a_1=4$ and $d=3$, $a_{10}=4+9\\times3=31$.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":1745,"Order":1,"LatexCode":"30","IsCorrect":false},{"Id":1746,"Order":2,"LatexCode":"34","IsCorrect":false},{"Id":1747,"Order":3,"LatexCode":"27","IsCorrect":false},{"Id":1748,"Order":4,"LatexCode":"31","IsCorrect":true}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"حدد عدد الانتقالات من الحد الأول.","En":"Count the transitions from the first term."},{"Ar":"اضرب الفرق في عدد الانتقالات وأضف الحد الأول.","En":"Multiply the difference by the transitions and add the first term."}],"Title":{"Ar":"حساب حد محدد من متتالية حسابية","En":"Find a specified term of an arithmetic progression"},"Points":10,"Options":[{"Reason":{"Ar":"30 لا يساوي 4 مضافاً إليها تسعة فروق مقدار كل منها 3.","En":"30 is not 4 plus nine increments of 3."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"30"},{"Reason":{"Ar":"34 ينتج عن عشر انتقالات بدلاً من تسعة.","En":"34 uses ten transitions instead of nine."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"34"},{"Reason":{"Ar":"27 هو مجموع الزيادات دون الحد الأول.","En":"27 is the total increase without the first term."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"27"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"31"}],"StageId":3,"Question":{"Ar":"متتالية حسابية حدها الأول 4 وفرقها المشترك 3. أوجد الحد العاشر.","En":"An arithmetic sequence has first term 4 and common difference 3. Find the tenth term."},"Solution":{"Idea":{"Ar":"الحد العام لمتتالية حسابية يضيف الفرق المشترك بعدد الانتقالات.","En":"The nth arithmetic term adds the common difference once per transition."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"عدد الانتقالات من الرتبة 1 إلى 10 هو $10-1=9$.","En":"The number of transitions from index 1 to 10 is $10-1=9$."},{"Ar":"كل انتقال يضيف 3؛ إذن الزيادة $9\\times3=27$.","En":"Each transition adds 3; the total increase is $9\\times3=27$."},{"Ar":"نضيف الحد الأول: $4+27=31$.","En":"Add the first term: $4+27=31$."}],"Result":{"Ar":"$31$","En":"$31$"},"CommonError":{"Ar":"الحد العاشر يحتاج تسع انتقالات لا عشر.","En":"The tenth term needs nine transitions, not ten."},"FormulaLatex":"a_n=a_1+(n-1)d","Substitution":{"Ar":"$a_{10}=4+9\\times3=31$","En":"$a_{10}=4+9\\times3=31$"},"Verification":{"Ar":"$31-4=27=9\\times3$","En":"$31-4=27=9\\times3$"}},"TrackIds":[10],"CategoryId":23,"PrimarySkillId":104,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"حدد عدد الانتقالات من الحد الأول.","En":"Count the transitions from the first term."},{"Ar":"اضرب الفرق في عدد الانتقالات وأضف الحد الأول.","En":"Multiply the difference by the transitions and add the first term."}],"Solution":{"Idea":{"Ar":"الحد العام لمتتالية حسابية يضيف الفرق المشترك بعدد الانتقالات.","En":"The nth arithmetic term adds the common difference once per transition."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"عدد الانتقالات من الرتبة 1 إلى 10 هو $10-1=9$.","En":"The number of transitions from index 1 to 10 is $10-1=9$."},{"Ar":"كل انتقال يضيف 3؛ إذن الزيادة $9\\times3=27$.","En":"Each transition adds 3; the total increase is $9\\times3=27$."},{"Ar":"نضيف الحد الأول: $4+27=31$.","En":"Add the first term: $4+27=31$."}],"Result":{"Ar":"$31$","En":"$31$"},"CommonError":{"Ar":"الحد العاشر يحتاج تسع انتقالات لا عشر.","En":"The tenth term needs nine transitions, not ten."},"FormulaLatex":"a_n=a_1+(n-1)d","Substitution":{"Ar":"$a_{10}=4+9\\times3=31$","En":"$a_{10}=4+9\\times3=31$"},"Verification":{"Ar":"$31-4=27=9\\times3$","En":"$31-4=27=9\\times3$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"30 لا يساوي 4 مضافاً إليها تسعة فروق مقدار كل منها 3.","En":"30 is not 4 plus nine increments of 3."},"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"34 ينتج عن عشر انتقالات بدلاً من تسعة.","En":"34 uses ten transitions instead of nine."},"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"27 هو مجموع الزيادات دون الحد الأول.","En":"27 is the total increase without the first term."},"Order":3},{"ErrorType":"","Reason":null,"Order":4}]}$mw$,$mw$الحد العام لمتتالية حسابية يضيف الفرق المشترك بعدد الانتقالات.

$a_n=a_1+(n-1)d$

1. عدد الانتقالات من الرتبة 1 إلى 10 هو $10-1=9$.

2. كل انتقال يضيف 3؛ إذن الزيادة $9\times3=27$.

3. نضيف الحد الأول: $4+27=31$.

$a_{10}=4+9\times3=31$

$31$ بلا وحدة قياس

$31-4=27=9\times3$

الحد العاشر يحتاج تسع انتقالات لا عشر.$mw$,$mw$The nth arithmetic term adds the common difference once per transition.

$a_n=a_1+(n-1)d$

1. The number of transitions from index 1 to 10 is $10-1=9$.

2. Each transition adds 3; the total increase is $9\times3=27$.

3. Add the first term: $4+27=31$.

$a_{10}=4+9\times3=31$

$31$ Dimensionless

$31-4=27=9\times3$

The tenth term needs nine transitions, not ten.$mw$),
(615,440,$mw$31E111A9CF7849A1A766178CF4DB276E87673CC6FB239114AB1F8740B3C29F67$mw$,$mw$860176f0ae037b524318d97cc265bd47$mw$,$mw$$mw$,$mw${"Id":440,"StageId":3,"CategoryId":23,"Points":10,"TitleAr":"حساب مجموع متتالية حسابية منتهية","TitleEn":"Sum a finite arithmetic progression","QuestionTextAr":"احسب مجموع الحدود الستة: 2، 5، 8، 11، 14، 17.","QuestionTextEn":"Find the sum of the six terms 2, 5, 8, 11, 14, 17.","DetailedSolutionAr":"قانون مجموع أول ن حدود في متتالية حسابية: مₙ = (ن ÷ 2) × (الحد الأول + الحد الأخير). لدينا ستة حدود من 2 حتى 17 بفرق ثابت 3. بالتعويض: م₆ = (6 ÷ 2) × (2 + 17) = 3 × 19 = 57. ويمكن التأكد بالجمع 2 + 5 + 8 + 11 + 14 + 17 = 57.","DetailedSolutionEn":"Arithmetic series sum law: S_n = n(first + last)/2. The six terms run from 2 through 17 with common difference 3. Thus S₆ = 6(2 + 17)/2 = 3 × 19 = 57. Direct check: 2 + 5 + 8 + 11 + 14 + 17 = 57.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":1749,"Order":1,"LatexCode":"60","IsCorrect":false},{"Id":1750,"Order":2,"LatexCode":"57","IsCorrect":true},{"Id":1751,"Order":3,"LatexCode":"51","IsCorrect":false},{"Id":1752,"Order":4,"LatexCode":"54","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"لاحظ أن الفرق بين الحدود ثابت.","En":"Notice the constant difference."},{"Ar":"اجمع الطرفين واضرب بنصف عدد الحدود.","En":"Add the endpoints and multiply by half the term count."}],"Title":{"Ar":"حساب مجموع متتالية حسابية منتهية","En":"Sum a finite arithmetic progression"},"Points":10,"Options":[{"Reason":{"Ar":"60 يعني متوسط 10 للحدود الستة، لكن متوسط الطرفين 9.5.","En":"60 would imply a mean of 10 for six terms, but the endpoint average is 9.5."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"60"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"57"},{"Reason":{"Ar":"51 يعني متوسط 8.5 لا 9.5.","En":"51 would imply a mean of 8.5, not 9.5."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"51"},{"Reason":{"Ar":"54 يعني متوسط 9 لا 9.5.","En":"54 would imply a mean of 9, not 9.5."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"54"}],"StageId":3,"Question":{"Ar":"احسب مجموع الحدود الستة: 2، 5، 8، 11، 14، 17.","En":"Find the sum of the six terms 2, 5, 8, 11, 14, 17."},"Solution":{"Idea":{"Ar":"نجمع المتتالية الحسابية بضرب عدد الحدود في متوسط الطرفين.","En":"Sum an arithmetic sequence by multiplying the count by the average of the endpoints."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"الفروق بين الحدود تساوي 3، لذا المتتالية حسابية وعدد حدودها 6.","En":"Successive differences are 3, so this is an arithmetic sequence with six terms."},{"Ar":"مجموع أول وآخر حد $2+17=19$؛ وكل زوج متناظر له المجموع نفسه.","En":"The first and last terms sum to $2+17=19$; each symmetric pair has the same sum."},{"Ar":"توجد ثلاثة أزواج، إذن $3\\times19=57$.","En":"There are three pairs, so $3\\times19=57$."}],"Result":{"Ar":"$57$","En":"$57$"},"CommonError":{"Ar":"لا تستعمل عدد الانتقالات بدلاً من عدد الحدود.","En":"Do not use the transition count instead of the term count."},"FormulaLatex":"S_n=\\frac{n(a_1+a_n)}2","Substitution":{"Ar":"$S_6=\\frac{6(2+17)}2=57$","En":"$S_6=\\frac{6(2+17)}2=57$"},"Verification":{"Ar":"$(2+17)+(5+14)+(8+11)=57$","En":"$(2+17)+(5+14)+(8+11)=57$"}},"TrackIds":[11],"CategoryId":23,"PrimarySkillId":101,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"لاحظ أن الفرق بين الحدود ثابت.","En":"Notice the constant difference."},{"Ar":"اجمع الطرفين واضرب بنصف عدد الحدود.","En":"Add the endpoints and multiply by half the term count."}],"Solution":{"Idea":{"Ar":"نجمع المتتالية الحسابية بضرب عدد الحدود في متوسط الطرفين.","En":"Sum an arithmetic sequence by multiplying the count by the average of the endpoints."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"الفروق بين الحدود تساوي 3، لذا المتتالية حسابية وعدد حدودها 6.","En":"Successive differences are 3, so this is an arithmetic sequence with six terms."},{"Ar":"مجموع أول وآخر حد $2+17=19$؛ وكل زوج متناظر له المجموع نفسه.","En":"The first and last terms sum to $2+17=19$; each symmetric pair has the same sum."},{"Ar":"توجد ثلاثة أزواج، إذن $3\\times19=57$.","En":"There are three pairs, so $3\\times19=57$."}],"Result":{"Ar":"$57$","En":"$57$"},"CommonError":{"Ar":"لا تستعمل عدد الانتقالات بدلاً من عدد الحدود.","En":"Do not use the transition count instead of the term count."},"FormulaLatex":"S_n=\\frac{n(a_1+a_n)}2","Substitution":{"Ar":"$S_6=\\frac{6(2+17)}2=57$","En":"$S_6=\\frac{6(2+17)}2=57$"},"Verification":{"Ar":"$(2+17)+(5+14)+(8+11)=57$","En":"$(2+17)+(5+14)+(8+11)=57$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"60 يعني متوسط 10 للحدود الستة، لكن متوسط الطرفين 9.5.","En":"60 would imply a mean of 10 for six terms, but the endpoint average is 9.5."},"Order":1},{"ErrorType":"","Reason":null,"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"51 يعني متوسط 8.5 لا 9.5.","En":"51 would imply a mean of 8.5, not 9.5."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"54 يعني متوسط 9 لا 9.5.","En":"54 would imply a mean of 9, not 9.5."},"Order":4}]}$mw$,$mw$نجمع المتتالية الحسابية بضرب عدد الحدود في متوسط الطرفين.

$S_n=\frac{n(a_1+a_n)}2$

1. الفروق بين الحدود تساوي 3، لذا المتتالية حسابية وعدد حدودها 6.

2. مجموع أول وآخر حد $2+17=19$؛ وكل زوج متناظر له المجموع نفسه.

3. توجد ثلاثة أزواج، إذن $3\times19=57$.

$S_6=\frac{6(2+17)}2=57$

$57$ بلا وحدة قياس

$(2+17)+(5+14)+(8+11)=57$

لا تستعمل عدد الانتقالات بدلاً من عدد الحدود.$mw$,$mw$Sum an arithmetic sequence by multiplying the count by the average of the endpoints.

$S_n=\frac{n(a_1+a_n)}2$

1. Successive differences are 3, so this is an arithmetic sequence with six terms.

2. The first and last terms sum to $2+17=19$; each symmetric pair has the same sum.

3. There are three pairs, so $3\times19=57$.

$S_6=\frac{6(2+17)}2=57$

$57$ Dimensionless

$(2+17)+(5+14)+(8+11)=57$

Do not use the transition count instead of the term count.$mw$),
(616,441,$mw$FA733C7E41D739E3AAC6F4DED94EA2B33B5CD2CF82429769999EB447FC902011$mw$,$mw$20ca7ad371ffe022b35515298e8ec311$mw$,$mw$$mw$,$mw${"Id":441,"StageId":3,"CategoryId":23,"Points":10,"TitleAr":"حساب مجموع متسلسلة هندسية منتهية","TitleEn":"Sum a finite geometric series","QuestionTextAr":"احسب $1+2+4+8+16$.","QuestionTextEn":"Compute $1+2+4+8+16$.","DetailedSolutionAr":"قانون مجموع متتالية هندسية منتهية: مₙ = أ₁(rⁿ − 1)/(r − 1) عندما r ≠ 1. للأعداد 1، 2، 4، 8، 16 الحد الأول 1 والنسبة المشتركة 2 وعدد الحدود 5. إذن م₅ = 1 × (2⁵ − 1)/(2 − 1) = 32 − 1 = 31. والتحقق بالجمع المباشر يعطي 31.","DetailedSolutionEn":"Finite geometric sum rule: S_n = a₁(r^n − 1)/(r − 1) for r ≠ 1. Here first term = 1, ratio = 2 and n = 5. Substitute: S₅ = 1 × (2⁵ − 1)/(2 − 1) = 32 − 1 = 31. The direct sum 1 + 2 + 4 + 8 + 16 also equals 31.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":1753,"Order":1,"LatexCode":"31","IsCorrect":true},{"Id":1754,"Order":2,"LatexCode":"30","IsCorrect":false},{"Id":1755,"Order":3,"LatexCode":"32","IsCorrect":false},{"Id":1756,"Order":4,"LatexCode":"15","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"حدد النسبة المشتركة وعدد الحدود.","En":"Identify the common ratio and number of terms."},{"Ar":"استعمل صيغة المجموع الهندسي المنتهي.","En":"Use the finite geometric sum formula."}],"Title":{"Ar":"حساب مجموع متسلسلة هندسية منتهية","En":"Sum a finite geometric series"},"Points":10,"Options":[{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"31"},{"Reason":{"Ar":"30 هو المجموع بعد حذف الحد الأول 1.","En":"30 is the sum after omitting the first term 1."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"30"},{"Reason":{"Ar":"32 يساوي القوة التالية، وليس مجموع القوى الخمس.","En":"32 is the next power, not the sum of the five powers."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"32"},{"Reason":{"Ar":"15 هو مجموع أول أربعة حدود فقط.","En":"15 is the sum of the first four terms only."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"15"}],"StageId":3,"Question":{"Ar":"احسب $1+2+4+8+16$.","En":"Compute $1+2+4+8+16$."},"Solution":{"Idea":{"Ar":"مجموع متسلسلة هندسية منتهية يحسب بصيغة مجموع القوى.","En":"A finite geometric sum follows the geometric-series formula."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"الحد الأول 1، والنسبة المشتركة 2، وعدد الحدود 5.","En":"The first term is 1, the common ratio is 2, and there are five terms."},{"Ar":"بما أن $r=2\\ne1$ نستعمل صيغة المجموع المنتهي.","En":"Since $r=2\\ne1$, use the finite-sum formula."},{"Ar":"نحسب $(2^5-1)/(2-1)=(32-1)/1=31$.","En":"Calculate $(2^5-1)/(2-1)=(32-1)/1=31$."}],"Result":{"Ar":"$31$","En":"$31$"},"CommonError":{"Ar":"لا تستخدم صيغة المجموع اللانهائي لنسبة أكبر من واحد.","En":"Do not use the infinite-sum formula for a ratio above one."},"FormulaLatex":"S_n=a_1\\frac{r^n-1}{r-1}\\quad(r\\ne1)","Substitution":{"Ar":"$S_5=(2^5-1)/(2-1)=31$","En":"$S_5=(2^5-1)/(2-1)=31$"},"Verification":{"Ar":"$1+2+4+8+16=31$","En":"$1+2+4+8+16=31$"}},"TrackIds":[11],"CategoryId":23,"PrimarySkillId":101,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"حدد النسبة المشتركة وعدد الحدود.","En":"Identify the common ratio and number of terms."},{"Ar":"استعمل صيغة المجموع الهندسي المنتهي.","En":"Use the finite geometric sum formula."}],"Solution":{"Idea":{"Ar":"مجموع متسلسلة هندسية منتهية يحسب بصيغة مجموع القوى.","En":"A finite geometric sum follows the geometric-series formula."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"الحد الأول 1، والنسبة المشتركة 2، وعدد الحدود 5.","En":"The first term is 1, the common ratio is 2, and there are five terms."},{"Ar":"بما أن $r=2\\ne1$ نستعمل صيغة المجموع المنتهي.","En":"Since $r=2\\ne1$, use the finite-sum formula."},{"Ar":"نحسب $(2^5-1)/(2-1)=(32-1)/1=31$.","En":"Calculate $(2^5-1)/(2-1)=(32-1)/1=31$."}],"Result":{"Ar":"$31$","En":"$31$"},"CommonError":{"Ar":"لا تستخدم صيغة المجموع اللانهائي لنسبة أكبر من واحد.","En":"Do not use the infinite-sum formula for a ratio above one."},"FormulaLatex":"S_n=a_1\\frac{r^n-1}{r-1}\\quad(r\\ne1)","Substitution":{"Ar":"$S_5=(2^5-1)/(2-1)=31$","En":"$S_5=(2^5-1)/(2-1)=31$"},"Verification":{"Ar":"$1+2+4+8+16=31$","En":"$1+2+4+8+16=31$"}},"Distractors":[{"ErrorType":"","Reason":null,"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"30 هو المجموع بعد حذف الحد الأول 1.","En":"30 is the sum after omitting the first term 1."},"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"32 يساوي القوة التالية، وليس مجموع القوى الخمس.","En":"32 is the next power, not the sum of the five powers."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"15 هو مجموع أول أربعة حدود فقط.","En":"15 is the sum of the first four terms only."},"Order":4}]}$mw$,$mw$مجموع متسلسلة هندسية منتهية يحسب بصيغة مجموع القوى.

$S_n=a_1\frac{r^n-1}{r-1}\quad(r\ne1)$

1. الحد الأول 1، والنسبة المشتركة 2، وعدد الحدود 5.

2. بما أن $r=2\ne1$ نستعمل صيغة المجموع المنتهي.

3. نحسب $(2^5-1)/(2-1)=(32-1)/1=31$.

$S_5=(2^5-1)/(2-1)=31$

$31$ بلا وحدة قياس

$1+2+4+8+16=31$

لا تستخدم صيغة المجموع اللانهائي لنسبة أكبر من واحد.$mw$,$mw$A finite geometric sum follows the geometric-series formula.

$S_n=a_1\frac{r^n-1}{r-1}\quad(r\ne1)$

1. The first term is 1, the common ratio is 2, and there are five terms.

2. Since $r=2\ne1$, use the finite-sum formula.

3. Calculate $(2^5-1)/(2-1)=(32-1)/1=31$.

$S_5=(2^5-1)/(2-1)=31$

$31$ Dimensionless

$1+2+4+8+16=31$

Do not use the infinite-sum formula for a ratio above one.$mw$),
(617,442,$mw$52269A2CC06B93335D610DFCA923169D8D91D203C7F9B8A0DD5AA9453F8C8CB7$mw$,$mw$cef7dad170445340c36914b96f42b259$mw$,$mw$$mw$,$mw${"Id":442,"StageId":3,"CategoryId":23,"Points":10,"TitleAr":"تحديد التقارب وحساب مجموع متسلسلة هندسية لا نهائية","TitleEn":"Check convergence and sum an infinite geometric series","QuestionTextAr":"أوجد مجموع المتسلسلة الهندسية اللانهائية $4+2+1+\\frac12+\\cdots$.","QuestionTextEn":"Find the sum of the infinite geometric series $4+2+1+\\frac12+\\cdots$.","DetailedSolutionAr":"قانون مجموع المتسلسلة الهندسية اللانهائية: S = أ₁/(1−r) بشرط |r| < 1. للمتسلسلة 4 + 2 + 1 + 1/2 + ... نجد الحد الأول أ₁ = 4 والنسبة المشتركة r = 2/4 = 1/2. بالتعويض: S = 4/(1−1/2) = 4/(1/2) = 8.","DetailedSolutionEn":"Infinite geometric-series sum law: S = a₁/(1−r) when |r|<1. For 4+2+1+1/2+..., a₁=4 and r=2/4=1/2. The ratio has absolute value below one, so the series converges. Substitute S=4/(1−1/2)=8.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":1757,"Order":1,"LatexCode":"4","IsCorrect":false},{"Id":1758,"Order":2,"LatexCode":"\\infty","IsCorrect":false},{"Id":1759,"Order":3,"LatexCode":"8","IsCorrect":true},{"Id":1760,"Order":4,"LatexCode":"7","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"حدد النسبة بين حدين متتاليين.","En":"Find the ratio of consecutive terms."},{"Ar":"تحقق من شرط التقارب ثم استخدم صيغة المجموع اللانهائي.","En":"Check the convergence condition, then use the infinite-sum formula."}],"Title":{"Ar":"تحديد التقارب وحساب مجموع متسلسلة هندسية لا نهائية","En":"Check convergence and sum an infinite geometric series"},"Points":10,"Options":[{"Reason":{"Ar":"4 هو الحد الأول، وتوجد بعده حدود موجبة أخرى.","En":"4 is the first term, followed by further positive terms."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"4"},{"Reason":{"Ar":"المتسلسلة متقاربة لأن القيمة المطلقة للنسبة أصغر من واحد.","En":"The series converges because the absolute ratio is below one."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"\\infty"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"8"},{"Reason":{"Ar":"7 مجموع الحدود الثلاثة الأولى فقط.","En":"7 is only the sum of the first three terms."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"7"}],"StageId":3,"Question":{"Ar":"أوجد مجموع المتسلسلة الهندسية اللانهائية $4+2+1+\\frac12+\\cdots$.","En":"Find the sum of the infinite geometric series $4+2+1+\\frac12+\\cdots$."},"Solution":{"Idea":{"Ar":"المتسلسلة الهندسية تتقارب عندما تكون القيمة المطلقة للنسبة أصغر من واحد.","En":"A geometric series converges when the absolute ratio is below one."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"الحد الأول $a_1=4$ والنسبة $r=2/4=1/2$.","En":"The first term is $a_1=4$ and the ratio is $r=2/4=1/2$."},{"Ar":"بما أن $|r|=1/2<1$ فإن المجموع اللانهائي موجود.","En":"Since $|r|=1/2<1$, the infinite sum exists."},{"Ar":"نحسب $4/(1-1/2)=4/(1/2)=8$.","En":"Calculate $4/(1-1/2)=4/(1/2)=8$."}],"Result":{"Ar":"$8$","En":"$8$"},"CommonError":{"Ar":"لا تجمع عدداً محدوداً من الحدود ثم تعتبره المجموع اللانهائي.","En":"Do not mistake a finite partial sum for the infinite sum."},"FormulaLatex":"S_\\infty=\\frac{a_1}{1-r}\\quad(|r|<1)","Substitution":{"Ar":"$r=1/2,\\quad S=4/(1-1/2)=8$","En":"$r=1/2,\\quad S=4/(1-1/2)=8$"},"Verification":{"Ar":"$S-\\tfrac12 S=4$","En":"$S-\\tfrac12 S=4$"}},"TrackIds":[12],"CategoryId":23,"PrimarySkillId":101,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"حدد النسبة بين حدين متتاليين.","En":"Find the ratio of consecutive terms."},{"Ar":"تحقق من شرط التقارب ثم استخدم صيغة المجموع اللانهائي.","En":"Check the convergence condition, then use the infinite-sum formula."}],"Solution":{"Idea":{"Ar":"المتسلسلة الهندسية تتقارب عندما تكون القيمة المطلقة للنسبة أصغر من واحد.","En":"A geometric series converges when the absolute ratio is below one."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"الحد الأول $a_1=4$ والنسبة $r=2/4=1/2$.","En":"The first term is $a_1=4$ and the ratio is $r=2/4=1/2$."},{"Ar":"بما أن $|r|=1/2<1$ فإن المجموع اللانهائي موجود.","En":"Since $|r|=1/2<1$, the infinite sum exists."},{"Ar":"نحسب $4/(1-1/2)=4/(1/2)=8$.","En":"Calculate $4/(1-1/2)=4/(1/2)=8$."}],"Result":{"Ar":"$8$","En":"$8$"},"CommonError":{"Ar":"لا تجمع عدداً محدوداً من الحدود ثم تعتبره المجموع اللانهائي.","En":"Do not mistake a finite partial sum for the infinite sum."},"FormulaLatex":"S_\\infty=\\frac{a_1}{1-r}\\quad(|r|<1)","Substitution":{"Ar":"$r=1/2,\\quad S=4/(1-1/2)=8$","En":"$r=1/2,\\quad S=4/(1-1/2)=8$"},"Verification":{"Ar":"$S-\\tfrac12 S=4$","En":"$S-\\tfrac12 S=4$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"4 هو الحد الأول، وتوجد بعده حدود موجبة أخرى.","En":"4 is the first term, followed by further positive terms."},"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"المتسلسلة متقاربة لأن القيمة المطلقة للنسبة أصغر من واحد.","En":"The series converges because the absolute ratio is below one."},"Order":2},{"ErrorType":"","Reason":null,"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"7 مجموع الحدود الثلاثة الأولى فقط.","En":"7 is only the sum of the first three terms."},"Order":4}]}$mw$,$mw$المتسلسلة الهندسية تتقارب عندما تكون القيمة المطلقة للنسبة أصغر من واحد.

$S_\infty=\frac{a_1}{1-r}\quad(|r|<1)$

1. الحد الأول $a_1=4$ والنسبة $r=2/4=1/2$.

2. بما أن $|r|=1/2<1$ فإن المجموع اللانهائي موجود.

3. نحسب $4/(1-1/2)=4/(1/2)=8$.

$r=1/2,\quad S=4/(1-1/2)=8$

$8$ بلا وحدة قياس

$S-\tfrac12 S=4$

لا تجمع عدداً محدوداً من الحدود ثم تعتبره المجموع اللانهائي.$mw$,$mw$A geometric series converges when the absolute ratio is below one.

$S_\infty=\frac{a_1}{1-r}\quad(|r|<1)$

1. The first term is $a_1=4$ and the ratio is $r=2/4=1/2$.

2. Since $|r|=1/2<1$, the infinite sum exists.

3. Calculate $4/(1-1/2)=4/(1/2)=8$.

$r=1/2,\quad S=4/(1-1/2)=8$

$8$ Dimensionless

$S-\tfrac12 S=4$

Do not mistake a finite partial sum for the infinite sum.$mw$),
(618,443,$mw$497E91919C88BDCDBB2F49C2A4D3EC0B8CCBFF82673AB207DBC61B9018311C1F$mw$,$mw$920c6dc8989e9101bfac6fba1b0bfadf$mw$,$mw$$mw$,$mw${"Id":443,"StageId":3,"CategoryId":23,"Points":10,"TitleAr":"تطبيق علاقة عودية لحساب الحدود المتتابعة","TitleEn":"Evaluate successive terms from a recurrence","QuestionTextAr":"إذا $a_1=2$ و$a_{n+1}=2a_n+1$، أوجد $a_3$.","QuestionTextEn":"If $a_1=2$ and $a_{n+1}=2a_n+1$, find $a_3$.","DetailedSolutionAr":"المبدأ المستخدم: في المتتالية المعرفة بالعلاقة العودية نحسب كل حد بالاعتماد على سابقه. المعطى أ₁ = 2 و أₙ₊₁ = 2أₙ + 1. نحسب أ₂ = 2 × 2 + 1 = 5، ثم أ₃ = 2 × 5 + 1 = 11. إذن الحد الثالث هو 11، ولا نستطيع تجاوز حساب الحد الثاني في هذه العلاقة.","DetailedSolutionEn":"Rule used: A recurrence defines each term from the preceding term. Given a₁ = 2 and a_(n+1) = 2a_n + 1, compute a₂ = 2 × 2 + 1 = 5, then a₃ = 2 × 5 + 1 = 11. Therefore the third term is 11.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":1761,"Order":1,"LatexCode":"5","IsCorrect":false},{"Id":1762,"Order":2,"LatexCode":"9","IsCorrect":false},{"Id":1763,"Order":3,"LatexCode":"12","IsCorrect":false},{"Id":1764,"Order":4,"LatexCode":"11","IsCorrect":true}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"ابدأ بالحد الأول المعطى.","En":"Start with the given first term."},{"Ar":"طبق علاقة التراجع مرتين بالتتابع.","En":"Apply the recurrence twice in succession."}],"Title":{"Ar":"تطبيق علاقة عودية لحساب الحدود المتتابعة","En":"Evaluate successive terms from a recurrence"},"Points":10,"Options":[{"Reason":{"Ar":"5 هو الحد الثاني لا الثالث.","En":"5 is the second term, not the third."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"5"},{"Reason":{"Ar":"9 لا يساوي ضعف الحد الثاني 5 مضافاً إليه 1.","En":"9 is not twice the second term 5 plus 1."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"9"},{"Reason":{"Ar":"12 لا يحقق العلاقة من الحد الثاني: 2×5+1=11.","En":"12 fails the recurrence from the second term: 2×5+1=11."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"12"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"11"}],"StageId":3,"Question":{"Ar":"إذا $a_1=2$ و$a_{n+1}=2a_n+1$، أوجد $a_3$.","En":"If $a_1=2$ and $a_{n+1}=2a_n+1$, find $a_3$."},"Solution":{"Idea":{"Ar":"علاقة التراجع تحدد كل حد باستعمال الحد السابق.","En":"The recurrence determines each term from its predecessor."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"نعوض $a_1=2$ في العلاقة لنجد $a_2=2(2)+1=5$.","En":"Substitute $a_1=2$ into the recurrence to get $a_2=2(2)+1=5$."},{"Ar":"نستخدم الحد الجديد لا الأول: $a_3=2(5)+1=11$.","En":"Use the new term, not the first: $a_3=2(5)+1=11$."}],"Result":{"Ar":"$11$","En":"$11$"},"CommonError":{"Ar":"لا تستخدم الحد الأول في الخطوتين.","En":"Do not reuse the first term for both transitions."},"FormulaLatex":"a_{n+1}=2a_n+1","Substitution":{"Ar":"$a_2=2(2)+1=5,\\quad a_3=2(5)+1=11$","En":"$a_2=2(2)+1=5,\\quad a_3=2(5)+1=11$"},"Verification":{"Ar":"$(11-1)/2=5$","En":"$(11-1)/2=5$"}},"TrackIds":[11],"CategoryId":23,"PrimarySkillId":102,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"ابدأ بالحد الأول المعطى.","En":"Start with the given first term."},{"Ar":"طبق علاقة التراجع مرتين بالتتابع.","En":"Apply the recurrence twice in succession."}],"Solution":{"Idea":{"Ar":"علاقة التراجع تحدد كل حد باستعمال الحد السابق.","En":"The recurrence determines each term from its predecessor."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"نعوض $a_1=2$ في العلاقة لنجد $a_2=2(2)+1=5$.","En":"Substitute $a_1=2$ into the recurrence to get $a_2=2(2)+1=5$."},{"Ar":"نستخدم الحد الجديد لا الأول: $a_3=2(5)+1=11$.","En":"Use the new term, not the first: $a_3=2(5)+1=11$."}],"Result":{"Ar":"$11$","En":"$11$"},"CommonError":{"Ar":"لا تستخدم الحد الأول في الخطوتين.","En":"Do not reuse the first term for both transitions."},"FormulaLatex":"a_{n+1}=2a_n+1","Substitution":{"Ar":"$a_2=2(2)+1=5,\\quad a_3=2(5)+1=11$","En":"$a_2=2(2)+1=5,\\quad a_3=2(5)+1=11$"},"Verification":{"Ar":"$(11-1)/2=5$","En":"$(11-1)/2=5$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"5 هو الحد الثاني لا الثالث.","En":"5 is the second term, not the third."},"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"9 لا يساوي ضعف الحد الثاني 5 مضافاً إليه 1.","En":"9 is not twice the second term 5 plus 1."},"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"12 لا يحقق العلاقة من الحد الثاني: 2×5+1=11.","En":"12 fails the recurrence from the second term: 2×5+1=11."},"Order":3},{"ErrorType":"","Reason":null,"Order":4}]}$mw$,$mw$علاقة التراجع تحدد كل حد باستعمال الحد السابق.

$a_{n+1}=2a_n+1$

1. نعوض $a_1=2$ في العلاقة لنجد $a_2=2(2)+1=5$.

2. نستخدم الحد الجديد لا الأول: $a_3=2(5)+1=11$.

$a_2=2(2)+1=5,\quad a_3=2(5)+1=11$

$11$ بلا وحدة قياس

$(11-1)/2=5$

لا تستخدم الحد الأول في الخطوتين.$mw$,$mw$The recurrence determines each term from its predecessor.

$a_{n+1}=2a_n+1$

1. Substitute $a_1=2$ into the recurrence to get $a_2=2(2)+1=5$.

2. Use the new term, not the first: $a_3=2(5)+1=11$.

$a_2=2(2)+1=5,\quad a_3=2(5)+1=11$

$11$ Dimensionless

$(11-1)/2=5$

Do not reuse the first term for both transitions.$mw$);
DO $audit$
DECLARE b record; d "CurriculumDraftItems"%ROWTYPE; p "Problems"%ROWTYPE; tr int; sk int; n int; actor int;
BEGIN
 FOR b IN SELECT * FROM reviewed_batch ORDER BY source LOOP
  PERFORM pg_advisory_xact_lock(-b.source::bigint);
  SELECT * INTO STRICT d FROM "CurriculumDraftItems" WHERE "Id"=b.draft FOR UPDATE;
  SELECT * INTO STRICT p FROM "Problems" WHERE "Id"=b.source FOR UPDATE;
  PERFORM 1 FROM "QuestionOptions" WHERE "ProblemId"=b.source FOR UPDATE;
  actor:=d."OwnerUserId"; tr:=(b.wizard->'TrackIds'->>0)::int; sk:=(b.wizard->>'PrimarySkillId')::int;
  IF d."SourceProblemId" IS DISTINCT FROM b.source OR d."Revision"<>0 OR d."EditorialStatus"<>'Draft' OR d."PublishedProblemId" IS NOT NULL OR d."SourceFingerprint" IS DISTINCT FROM b.fp OR md5(d."WizardJson") IS DISTINCT FROM b.draft_hash OR upper(encode(sha256(decode(b.source_hex,'hex')),'hex'))<>b.fp OR (SELECT json_build_object('Id',pp."Id",'StageId',pp."StageId",'CategoryId',pp."CategoryId",'Points',pp."Points",'TitleAr',pp."TitleAr",'TitleEn',pp."TitleEn",'QuestionTextAr',pp."QuestionTextAr",'QuestionTextEn',pp."QuestionTextEn",'DetailedSolutionAr',pp."DetailedSolutionAr",'DetailedSolutionEn',pp."DetailedSolutionEn",'YoutubeSolutionUrl',pp."YoutubeSolutionUrl",'EditorialDetailsJson',pp."EditorialDetailsJson",'Options',(select json_agg(json_build_object('Id',o."Id",'Order',o."Order",'LatexCode',o."LatexCode",'IsCorrect',o."IsCorrect") order by o."Order",o."Id") from "QuestionOptions" o where o."ProblemId"=pp."Id"))::jsonb FROM "Problems" pp WHERE pp."Id"=b.source) IS DISTINCT FROM b.snapshot THEN RAISE EXCEPTION 'Source/draft conflict: %',b.draft; END IF;
  IF NOT EXISTS(SELECT 1 FROM "Users" WHERE "Id"=actor AND "Role"='Admin' AND "IsActive" AND NOT "StaffSetupPending") OR (SELECT count(*) FROM "CurriculumDraftItems" WHERE "SourceProblemId"=b.source AND "EditorialStatus" NOT IN ('Published','Withdrawn'))<>1 THEN RAISE EXCEPTION 'Owner/open-draft conflict: %',b.draft; END IF;
  PERFORM 1 FROM "LearningTracks" WHERE "Id" IN (SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int) ORDER BY "Id" FOR UPDATE;
  IF NOT EXISTS(SELECT 1 FROM "LearningTracks" WHERE "Id"=tr AND "StageId"=p."StageId" AND "IsPublished" AND "Revision"<2147483647) OR NOT EXISTS(SELECT 1 FROM "Categories" WHERE "Id"=p."CategoryId" AND "StageId"=p."StageId") OR NOT EXISTS(SELECT 1 FROM "CurriculumSkills" s JOIN "CurriculumDomains" dm ON dm."Id"=s."DomainId" WHERE s."Id"=sk AND s."StageId"=p."StageId" AND s."CategoryId"=p."CategoryId" AND s."IsPublished" AND dm."IsPublished") OR NOT EXISTS(SELECT 1 FROM "LearningTrackCategories" WHERE "TrackId"=tr AND "CategoryId"=p."CategoryId") OR NOT EXISTS(SELECT 1 FROM "LearningTrackSkills" WHERE "TrackId"=tr AND "SkillId"=sk) OR (SELECT array_agg("TrackId" ORDER BY "TrackId") FROM "LearningTrackProblems" WHERE "ProblemId"=b.source) IS DISTINCT FROM ARRAY(SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int ORDER BY 1) OR (SELECT array_agg("SkillId" ORDER BY "SkillId") FROM "CurriculumProblemSkills" WHERE "ProblemId"=b.source) IS DISTINCT FROM ARRAY[sk] OR NOT EXISTS(SELECT 1 FROM "CurriculumProblemSkills" WHERE "ProblemId"=b.source AND "SkillId"=sk AND "IsPrimary") OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(b.wizard->'TrackIds') j(id) LEFT JOIN "LearningTracks" lt ON lt."Id"=j.id::int WHERE lt."Id" IS NULL OR lt."StageId"<>p."StageId" OR lt."Revision">=2147483647 OR NOT EXISTS(SELECT 1 FROM "LearningTrackCategories" WHERE "TrackId"=lt."Id" AND "CategoryId"=p."CategoryId") OR NOT EXISTS(SELECT 1 FROM "LearningTrackSkills" WHERE "TrackId"=lt."Id" AND "SkillId"=sk)) THEN RAISE EXCEPTION 'Scope conflict: %',b.draft; END IF;
  IF EXISTS(SELECT 1 FROM "Problems" q WHERE q."Id"<>b.source AND q."StageId"=p."StageId" AND (upper(regexp_replace(btrim(q."QuestionTextAr"),'[[:space:]]+',' ','g'))=upper(regexp_replace(btrim(p."QuestionTextAr"),'[[:space:]]+',' ','g')) OR upper(regexp_replace(btrim(q."QuestionTextEn"),'[[:space:]]+',' ','g'))=upper(regexp_replace(btrim(p."QuestionTextEn"),'[[:space:]]+',' ','g')))) THEN RAISE EXCEPTION 'Duplicate: %',b.draft; END IF;
  IF EXISTS(SELECT 1 FROM "CurriculumDraftItems" x WHERE x."Id"<>b.draft AND x."EditorialStatus" NOT IN ('Published','Withdrawn') AND (x."WizardJson"::jsonb#>>'{Question,Ar}'=p."QuestionTextAr" OR x."WizardJson"::jsonb#>>'{Question,En}'=p."QuestionTextEn")) THEN RAISE EXCEPTION 'Open draft duplicate: %',b.draft; END IF;
  IF b.wizard#>>'{Question,Ar}' IS DISTINCT FROM p."QuestionTextAr" OR b.wizard#>>'{Question,En}' IS DISTINCT FROM p."QuestionTextEn" OR length(b.flat_ar)>12000 OR length(b.flat_en)>12000 THEN RAISE EXCEPTION 'Question/length conflict: %',b.draft; END IF;
  UPDATE "Problems" SET "TitleAr"=b.wizard#>>'{Title,Ar}',"TitleEn"=b.wizard#>>'{Title,En}',"DetailedSolutionAr"=b.flat_ar,"DetailedSolutionEn"=b.flat_en,"EditorialDetailsJson"=b.metadata WHERE "Id"=b.source;
  UPDATE "CurriculumDraftItems" SET "WizardJson"=b.wizard::text,"EditorialStatus"='Published',"Revision"=4,"SubmittedAtUtc"=now(),"ReviewedAtUtc"=now(),"ReviewedByUserId"=actor,"ReviewNote"='Owner-authorized SQL maintenance; AI educational review and source-locked verification. Existing draft owner recorded for attribution; no API login.',"PublishedAtUtc"=now(),"PublishedProblemId"=b.source WHERE "Id"=b.draft;
  UPDATE "LearningTracks" SET "Revision"="Revision"+1 WHERE "Id" IN (SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int);
  INSERT INTO "PlatformActivityEvents"("ActorUserId","ActorRole","Action","Resource","ResourceId","Origin","CreatedAtUtc") SELECT actor,'Admin',action,'EditorialProblem',b.draft::text,'owner_sql',now() FROM unnest(ARRAY['EditorialDraftEdited','EditorialDraftSubmitted','EditorialDraftApproved','EditorialAmendmentPublished']) action;
 END LOOP;
END $audit$;
COMMIT;
